mapper.update:
update shopping_cart
set number = #{number}
where id=#{id};

mapper.delete:
delete
from shopping_cart
where user_id=#{userId}
  and dining_session_id is null;

delete
from shopping_cart
where user_id=#{userId}
  and dining_session_id=#{diningSessionId};

mapper.select:
select *
from shopping_cart

    and user_id=#{userId}
    and dish_id=#{dishId}
    and setmeal_id=#{setmealId}
    and dish_flavor=#{dishFlavor}

        and dining_session_id=#{diningSessionId}
        and dining_session_id is null


order by create_time desc
